import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"ADR-0006: Why Independent Verification","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-0006-why-independent-verification.md","filePath":"adr/ADR-0006-why-independent-verification.md","lastUpdated":1793381793000}`),a={name:`adr/ADR-0006-why-independent-verification.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="adr-0006-why-independent-verification" tabindex="-1">ADR-0006: Why Independent Verification <a class="header-anchor" href="#adr-0006-why-independent-verification" aria-label="Permalink to “ADR-0006: Why Independent Verification”">​</a></h1><ul><li>Status: Accepted</li><li>Date: 2026-10-31</li><li>Related: docs/guide/recovery-engine.md §6, probe-diagnosis.md §5</li></ul><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to “Background”">​</a></h2><p>The most convenient &quot;success&quot; signal for a recovery action is exit code 0 — but that only means the command ran: the process may have started and immediately died, the service may be up but not listening, the config may have been written but not applied. Trusting exit codes writes a false success back into the system, masks the real failure, triggers cooldown, and the failure is only passively discovered on the next probe.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Each recovery plan&#39;s verification field (default <code>status_is = &quot;healthy&quot;</code>) judges the result via the <strong>resource health probe</strong>: after the action runs, the run enters Verifying; only when the probe meets the condition does it transition to Recovered. Verification failure re-enters diagnosis (the fault may have changed) and proceeds to the next plan or attempt. P0 acceptance is explicit: when the command succeeds but the resource is still abnormal, recovery must not be reported as successful.</p><h2 id="alternatives" tabindex="-1">Alternatives <a class="header-anchor" href="#alternatives" aria-label="Permalink to “Alternatives”">​</a></h2><ul><li><strong>Trust exit code</strong>: false success (see background).</li><li><strong>Trust the action&#39;s own self-check output</strong>: action and verification share a source — it cannot detect errors in the action&#39;s own implementation.</li></ul><h2 id="pros-and-cons" tabindex="-1">Pros and Cons <a class="header-anchor" href="#pros-and-cons" aria-label="Permalink to “Pros and Cons”">​</a></h2><p>Pros: recovery success = observable health, not a command&#39;s echo; verification failure naturally links into re-diagnosis. Cons: verification waits for the next probe cycle (configurable convergence); probe quality becomes the floor for recovery correctness.</p><h2 id="follow-up-impact" tabindex="-1">Follow-up Impact <a class="header-anchor" href="#follow-up-impact" aria-label="Permalink to “Follow-up Impact”">​</a></h2><ul><li>VerificationResult is persisted — the audit chain answers &quot;why was recovery judged successful.&quot;</li><li>Both the engine event <code>recovery.verification</code> and the notification event <code>recovery.succeeded</code> are built on verification passing.</li></ul>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};